<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElInputNumber, ElMessage } from 'element-plus';
import { api } from '@/api/client';
import { useUnsavedGuard } from '@/composables/useUnsavedGuard';
import AdminShell from '@/components/AdminShell.vue';
import ErrorPanel from '@/components/ErrorPanel.vue';
import type { DifficultyMode, QuizSettings } from '@/types';
const settings = reactive<Pick<QuizSettings, 'questionCount' | 'modes'>>({ questionCount: 10, modes: { beginner: [0, 0, 0], proficient: [0, 0, 0], challenge: [0, 0, 0] } });
const { markSaved } = useUnsavedGuard(() => ({ questionCount: settings.questionCount, modes: { beginner: [...settings.modes.beginner], proficient: [...settings.modes.proficient], challenge: [...settings.modes.challenge] } }));
const ready = ref(false); const loading = ref(true); const saving = ref(false); const error = ref('');
const modeRows: { key: DifficultyMode; title: string; description: string }[] = [{ key: 'beginner', title: '新手级', description: '从基础字形开始' }, { key: 'proficient', title: '熟练级', description: '平衡观察与判断' }, { key: 'challenge', title: '挑战级', description: '挑战容易混淆的字形' }];
function sum(mode: DifficultyMode): number { return settings.modes[mode].reduce((total, value) => total + Number(value || 0), 0); }
function valid(mode: DifficultyMode): boolean { return sum(mode) > 0; }
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const current = await api.getAdminSettings(); settings.questionCount = current.questionCount; settings.modes = { beginner: [...current.modes.beginner], proficient: [...current.modes.proficient], challenge: [...current.modes.challenge] }; ready.value = true; markSaved(); } catch (caught) { error.value = caught instanceof Error ? caught.message : '出题策略加载失败。'; } finally { loading.value = false; } }
async function save(): Promise<void> { if (!modeRows.every((row) => valid(row.key))) { error.value = '每种难度至少要保留一个大于 0 的比例。'; return; } saving.value = true; error.value = ''; try { await api.saveStrategy({ questionCount: Number(settings.questionCount), modes: settings.modes }); ElMessage.success('出题策略已保存'); markSaved(); } catch (caught) { error.value = caught instanceof Error ? caught.message : '策略保存失败。'; } finally { saving.value = false; } }
onMounted(load);
</script>
<template><AdminShell><section class="admin-content"><header class="page-header"><div><p class="eyebrow">题库设置</p><h1 class="page-title">出题策略</h1><p class="page-description">设置每次练习的题数，并为三档星级题目分配目标比例。</p></div><div class="badge">1–3 星题库</div></header><div v-if="loading" class="loading card">正在读取出题策略…</div><ErrorPanel v-else-if="error && !ready" :message="error" @retry="load" /><form v-else class="strategy" @submit.prevent="save"><section class="card count-card"><div><p class="eyebrow">01 · 每次练习</p><h2>题目数量</h2></div><label><el-input-number v-model="settings.questionCount" :min="1" :max="50" controls-position="right" /> 题</label></section><section class="card"><p class="eyebrow">02 · 星级比例</p><h2>三档难度的抽题比例</h2><div class="matrix"><div class="matrix-heading"><span>练习模式</span><span v-for="star in 3" :key="star">{{ star }}★</span><span>合计</span></div><div v-for="row in modeRows" :key="row.key" class="matrix-row"><div><strong>{{ row.title }}</strong><small>{{ row.description }}</small></div><el-input-number v-for="(_, index) in settings.modes[row.key]" :key="index" v-model="settings.modes[row.key][index]" :min="0" :max="100" controls-position="right" /><strong :class="{ invalid: !valid(row.key) }">{{ sum(row.key) }}</strong></div></div></section><p v-if="error" class="status-error">{{ error }}</p><footer class="save-bar"><p>保存后，下一次练习立即使用新策略。</p><button :disabled="saving">{{ saving ? '正在保存…' : '保存出题策略' }}</button></footer></form></section></AdminShell></template>
<style scoped>.admin-content{width:min(960px,calc(100% - 64px));margin:auto;padding:48px 0 64px}.page-header,.count-card,.save-bar{display:flex;justify-content:space-between;gap:24px}.page-header{margin-bottom:28px}.page-description{margin-bottom:0}.badge{align-self:flex-start;border:1px solid #edcfac;border-radius:999px;padding:9px 12px;color:#93551e;background:#fff0d8;font-size:13px;font-weight:750}.loading,.card{padding:24px}.strategy{display:grid;gap:14px}.count-card{align-items:center}.count-card h2,.card h2{margin:4px 0 0;font-size:18px}.count-card label{display:flex;align-items:center;gap:8px;color:#93551e;font-weight:750}.matrix{overflow-x:auto;margin-top:18px}.matrix-heading,.matrix-row{display:grid;min-width:540px;grid-template-columns:1.7fr repeat(3,92px) 86px;align-items:center;gap:10px}.matrix-heading{padding-bottom:10px;color:var(--color-text-muted);font-size:12px;font-weight:750}.matrix-row{padding:14px 0;border-top:1px solid var(--color-border)}.matrix-row>div{display:grid;gap:4px}.matrix-row small{color:var(--color-text-muted)}.invalid{color:var(--color-danger)}.save-bar{align-items:center;padding:16px 20px;border:1px solid #efdbc1;border-radius:14px;background:#fff8ed}.save-bar p{margin:0;color:var(--color-text-muted);font-size:13px}.save-bar button{min-height:44px;border:0;border-radius:var(--radius-button);padding:0 20px;color:#fff;background:var(--color-action);font-weight:750}@media(max-width:760px){.admin-content{width:min(100% - 32px,960px);padding-top:28px}.page-header,.count-card,.save-bar{align-items:flex-start;flex-direction:column}.save-bar button{width:100%}}</style>
